package alphametics

import (
	"errors"
	"sort"
	"strings"
	"unicode"
)

// Solve returns the mapping of letters to digits that satisfies the puzzle,
// or an error if no valid solution exists.
func Solve(puzzle string) (map[string]int, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, errors.New("puzzle must have the form \"... == ...\"")
	}

	// Each letter accumulates a place-weighted coefficient: addends
	// contribute positively, the result contributes negatively. A solution
	// is an assignment of distinct digits such that the weighted sum is 0.
	coeff := map[rune]int64{}
	leading := map[rune]bool{}

	add := func(word string, sign int) error {
		for i, r := range word {
			if !unicode.IsLetter(r) {
				return errors.New("puzzle contains an invalid character")
			}
			place := int64(1)
			for j := i + 1; j < len(word); j++ {
				place *= 10
			}
			coeff[r] += sign * place
			if i == 0 && len(word) > 1 {
				leading[r] = true
			}
		}
		return nil
	}

	for _, word := range strings.Fields(strings.ReplaceAll(sides[0], "+", " ")) {
		if err := add(word, 1); err != nil {
			return nil, err
		}
	}
	for _, word := range strings.Fields(sides[1]) {
		if err := add(word, -1); err != nil {
			return nil, err
		}
	}

	letters := make([]rune, 0, len(coeff))
	for r := range coeff {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, errors.New("puzzle has more than ten distinct letters")
	}

	// Assign the most constraining letters first so the running sum is
	// checked against the remaining capacity early.
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeff[letters[i]]) > abs64(coeff[letters[j]])
	})

	assign := make([]int, len(letters))
	for i := range assign {
		assign[i] = -1
	}

	var solve func(idx int, used int, sum int64) bool
	solve = func(idx int, used int, sum int64) bool {
		if idx == len(letters) {
			return sum == 0
		}
		// Prune: even assigning every remaining letter its largest
		// possible contribution cannot bring the sum back to zero.
		if sum > 0 {
			if sum > remainingCapacity(letters, coeff, idx) {
				return false
			}
		} else if -sum > remainingCapacity(letters, coeff, idx) {
			return false
		}
		r := letters[idx]
		for d := 0; d <= 9; d++ {
			if used&(1<<d) != 0 {
				continue
			}
			if d == 0 && leading[r] {
				continue
			}
			assign[idx] = d
			if solve(idx+1, used|1<<d, sum+coeff[r]*int64(d)) {
				return true
			}
		}
		return false
	}

	if !solve(0, 0, 0) {
		return nil, errors.New("no solution exists")
	}

	out := make(map[string]int, len(letters))
	for i, r := range letters {
		out[string(r)] = assign[i]
	}
	return out, nil
}

// remainingCapacity bounds how much the letters at indices idx and later
// can still contribute, assuming each takes the largest magnitude digit.
func remainingCapacity(letters []rune, coeff map[rune]int64, idx int) int64 {
	var cap int64
	for _, r := range letters[idx:] {
		cap += 9 * abs64(coeff[r])
	}
	return cap
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

